import { useCallback, useState } from 'react';
import { Button, Modal, Stack, Text } from '@jinx-ui/react';

type DeleteProjectButtonProps = {
  projectName?: string;
  onConfirm: () => void;
};

export default function DeleteProjectButton({ projectName, onConfirm }: DeleteProjectButtonProps) {
  const [isOpen, setIsOpen] = useState(false);

  const close = useCallback(() => setIsOpen(false), []);

  const confirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={() => setIsOpen(true)}>
        Удалить проект
      </Button>

      <Modal open={isOpen} onClose={close} title="Удалить проект?" size="sm">
        <Stack gap="md" style={{ paddingBlock: 'var(--jx-space-2)' }}>
          <Text color="muted">
            {projectName
              ? `Проект «${projectName}» будет удалён без возможности восстановления.`
              : 'Проект будет удалён без возможности восстановления.'}{' '}
            Это действие необратимо.
          </Text>

          <Stack direction="row" gap="sm" justify="end">
            <Button variant="secondary" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={confirm}>
              Удалить
            </Button>
          </Stack>
        </Stack>
      </Modal>
    </>
  );
}

